1	// The task declaration contract (per-project-scheduling DESIGN §1) — the single
2	// source of truth for what a `tasks/<name>/task.mjs` default export must carry.
3	// Both the author-time `task-declaration-shape` check and the executor-side
4	// `validate-dispatch` validate against this one function, so the accepted shape
5	// can never drift between the two surfaces.
6	
7	import { FREQUENCIES } from './slots.mjs';
8	import { MODEL_FAMILIES } from './model-map.mjs';
9	
10	// A declared timeout is always a whole number of seconds, > 0.
11	const isPositiveInt = (n) => Number.isInteger(n) && n > 0;
12	
13	// A preprocessing command must stay inside its own task directory — no absolute
14	// path and no `..` traversal in the command string — the same containment the
15	// worker-file rule gives agent_instructions (agent-preprocessing DESIGN §2).
16	const escapesTaskDir = (cmd) => /(^|\s)\//.test(cmd) || cmd.includes('..');
17	
18	// The write ceiling a task declares (DESIGN §1, §4). A declared MAXIMUM, not a
19	// promise: `none` may never open a PR, `open-pr` may open but never merge,
20	// `merged-pr` may arm auto-merge. "No change" is always legal.
21	export const OUTCOMES = ['none', 'open-pr', 'merged-pr'];
22	
23	// The executor-session repo scope a task needs (per-project-scheduling split):
24	//   'self'  — the task touches only its own repo; a project-only executor session
25	//             is all it needs. This is the default, and almost every task's scope.
26	//   'fleet' — the task reaches across the owner's other repos (e.g. growth-promote
27	//             reads every member's local packs), so its dispatch goes to a
28	//             SEPARATE, broader-scoped executor. Isolating this to the few tasks
29	//             that truly need it keeps the fleet-wide session grant off every
30	//             ordinary project's executor. The scheduler routes a fleet task's
31	//             dispatch to the `ready-for-agent-fleet` label so a distinct executor
32	//             routine (with the owner's repos in its sources) runs it.
33	export const SESSION_SCOPES = ['self', 'fleet'];
34	
35	// The signal-collector vocabulary (DESIGN §3.3). A task collects only the union
36	// of what its due tasks declare. `fleet` is canon-only (consumers cannot declare
37	// it) — that restriction is enforced where signals are collected, not here; the
38	// shape check only asserts a declared name is a real collector.
39	export const SIGNAL_NAMES = [
40	  'commits', 'prs', 'issues', 'branches', 'release',
41	  'localPacks', 'sharedMount', 'conversationLogs', 'stamp', 'fleet',
42	];
43	
44	// Validate one task declaration. Returns an array of `{ what, fix }` problems —
45	// empty means the declaration is well-formed. Pure: no I/O, no imports of the
46	// task itself; the caller supplies the already-loaded default export.
47	export function validateTaskDeclaration(decl) {
48	  if (decl === null || typeof decl !== 'object' || Array.isArray(decl)) {
49	    return [{ what: 'task.mjs does not default-export a declaration object', fix: 'export default { id, frequency, precondition_signals, agent_model, expected_outcome, agent_instructions, precondition }' }];
50	  }
51	  const problems = [];
52	  const bad = (what, fix) => problems.push({ what, fix });
53	
54	  if (typeof decl.id !== 'string' || decl.id.trim() === '') {
55	    bad('the task has no string "id"', 'give the task an "id" matching its directory name');
56	  }
57	  if (!FREQUENCIES.includes(decl.frequency)) {
58	    bad(`"frequency" ${JSON.stringify(decl.frequency)} is not a legal frequency`, `set one of: ${FREQUENCIES.join(', ')}`);
59	  }
60	  if (!Array.isArray(decl.precondition_signals) || !decl.precondition_signals.every((s) => SIGNAL_NAMES.includes(s))) {
61	    bad(`"precondition_signals" must be an array of known signal names`, `use only: ${SIGNAL_NAMES.join(', ')}`);
62	  }
63	  if (!MODEL_FAMILIES.includes(decl.agent_model)) {
64	    bad(`"agent_model" ${JSON.stringify(decl.agent_model)} is not a legal model family`, `set one of: ${MODEL_FAMILIES.join(', ')}`);
65	  }
66	  if (!OUTCOMES.includes(decl.expected_outcome)) {
67	    bad(`"expected_outcome" ${JSON.stringify(decl.expected_outcome)} is not a legal outcome ceiling`, `set one of: ${OUTCOMES.join(', ')}`);
68	  }
69	  if (typeof decl.agent_instructions !== 'string' || decl.agent_instructions.trim() === '') {
70	    bad('the task has no string "agent_instructions"', 'point "agent_instructions" at the worker file beside task.mjs (e.g. "task.md")');
71	  }
72	  if (typeof decl.precondition !== 'function') {
73	    bad('"precondition" is not a function', 'export a precondition(signals, config) that returns { run, reason, context? }');
74	  }
75	
76	  // session_scope — OPTIONAL, defaults to 'self'. Only a task that reaches other
77	  // repos declares 'fleet' (routed to the fleet executor). A bad value would
78	  // silently mis-route the dispatch, so it is validated when present.
79	  if (decl.session_scope !== undefined && !SESSION_SCOPES.includes(decl.session_scope)) {
80	    bad(`"session_scope" ${JSON.stringify(decl.session_scope)} is not a legal session scope`, `omit it (defaults to "self") or set one of: ${SESSION_SCOPES.join(', ')}`);
81	  }
82	
83	  // Preprocessing (agent-preprocessing DESIGN §2) — OPTIONAL. A command the
84	  // scheduler runs as a subprocess before the agent. When present it must be a
85	  // non-empty, task-local command AND carry a positive-integer
86	  // agent_preprocessing_timeout — the hard kill that bounds the subprocess.
87	  if (decl.agent_preprocessing !== undefined) {
88	    if (typeof decl.agent_preprocessing !== 'string' || decl.agent_preprocessing.trim() === '') {
89	      bad('"agent_preprocessing" is present but not a non-empty string', 'set it to a command whose executable is a script beside task.mjs, e.g. "node prepare.mjs"');
90	    } else if (escapesTaskDir(decl.agent_preprocessing)) {
91	      bad('"agent_preprocessing" reaches outside the task directory (absolute path or "..")', 'reference a sibling script only, e.g. "node prepare.mjs"');
92	    }
93	    if (!isPositiveInt(decl.agent_preprocessing_timeout)) {
94	      bad('"agent_preprocessing" is set but "agent_preprocessing_timeout" is not a positive integer', 'add "agent_preprocessing_timeout": the seconds after which the subprocess is killed and the task fails');
95	    }
96	  }
97	
