1	// The scheduler entrypoint's orchestration core (per-project-scheduling DESIGN
2	// §3). The vendored hourly Action runs this: decide due slots from the run
3	// ledger, discover active tasks, collect only the signals the due tasks declare,
4	// run each precondition, and either dispatch agent work as a `ready-for-agent`
5	// issue or (for `agent_model: none`) run the worker inline.
6	//
7	// This module is the DECISION core, kept injectable so it tests with fakes: the
8	// GitHub I/O (the Actions run-ledger read for `lastSuccess`, the signal
9	// collectors, the issue search/create) is supplied by the thin CLI shell around
10	// `planRun`. The "should this run" verdict is always code here — never the
11	// shell's judgment (the same split the fleet planner uses).
12	
13	import { pathToFileURL } from 'node:url';
14	import { dueSlots } from './slots.mjs';
15	import {
16	  planDispatch, dispatchTitle, dispatchBody, DISPATCH_PREFIX, READY_LABEL, NEEDS_HUMAN_LABEL,
17	  SCHEDULER_LABELS, readyLabelForScope, staleDispatchIssues, staleEscalationComment,
18	  rearmDispatchIssues, readyLabelOn, staleClaimedDispatchIssues, staleClaimComment,
19	  AGENT_RUNNING_LABEL,
20	} from './dispatch.mjs';
21	import { isAgentless } from './model-map.mjs';
22	import { runPreprocessing, preprocessingFailure, agentRequestPath, clearAgentRequest, agentRequested } from './preprocess.mjs';
23	
24	// The due tasks, each paired with the slot it runs under. Union the discovered
25	// tasks' frequencies, ask slots which are due (run-ledger math), then map due
26	// frequencies back to their tasks. A task whose frequency isn't due drops out.
27	export function computeDueTaskSlots(tasks, schedule, now, lastSuccess) {
28	  const frequencies = [...new Set(tasks.map((t) => t.decl.frequency))];
29	  const due = new Map(dueSlots(frequencies, schedule, now, lastSuccess).map((d) => [d.frequency, d]));
30	  const out = [];
31	  for (const task of tasks) {
32	    const slot = due.get(task.decl.frequency);
33	    if (slot) out.push({ task, slotId: slot.slotId, slotTime: slot.slotTime });
34	  }
35	  return out;
36	}
37	
38	// The union of signal names the due tasks declare — the scheduler collects only
39	// these, so a non-daily slot never pays for daily tasks' signals (DESIGN §3.3).
40	export function signalsUnion(dueTaskSlots) {
41	  const names = new Set();
42	  for (const { task } of dueTaskSlots) for (const name of task.decl.precondition_signals) names.add(name);
43	  return [...names];
44	}
45	
46	// The signal-collection lookback: the widest due task's period plus 1h slack
47	// (DESIGN §3.3). Stateless fixed lookback — overlap is absorbed by dedupe.
48	const FREQUENCY_MS = {
49	  hourly: 3600e3, 'daily-2h': 86400e3, 'daily-1h': 86400e3, daily: 86400e3,
50	  'daily+1h': 86400e3, weekly: 7 * 86400e3, monthly: 31 * 86400e3,
51	};
52	export function windowStart(dueTaskSlots, now) {
53	  const widest = Math.max(0, ...dueTaskSlots.map(({ task }) => FREQUENCY_MS[task.decl.frequency] ?? 86400e3));
54	  return new Date(new Date(now).getTime() - widest - 3600e3).toISOString();
55	}
56	
57	// Run one task's precondition in isolation (DESIGN §3.4). A throwing
58	// precondition converges to a skip with the error recorded — it never sinks the
59	// rest of the run; the CLI escalates a thrown precondition to a workflow-failure
60	// issue separately.
61	export function runPrecondition(task, signals, packConfig) {
62	  try {
63	    const v = task.decl.precondition(signals, packConfig) ?? {};
64	    return {
65	      run: v.run === true,
66	      reason: v.reason ?? '',
67	      context: Array.isArray(v.context) ? v.context : [],
68	    };
69	  } catch (e) {
70	    return { run: false, reason: `precondition threw: ${e.message}`, context: [], error: e.message };
71	  }
72	}
73	
74	// A human-readable job-summary line per evaluated task — the observability the
75	// old plan.json gave (DESIGN §3.6).
76	export function renderSummary(evaluations) {
77	  return evaluations.map((e) => {
78	    const verb = !e.run ? 'skip' : e.inline ? 'run-inline' : e.dispatch?.action ?? 'run';
79	    return `- ${e.pack}/${e.task} [${e.slotId}] ${verb} — ${e.reason || e.dispatch?.reason || ''}`.trimEnd();
80	  }).join('\n');
81	}
82	
83	// Orchestrate one scheduler run into a set of decisions — the reusable core the
84	// CLI wraps with real GitHub I/O. Injected seams:
85	//   collectSignals(names) -> signals object (the declared union, collected once)
86	//   packConfigFor(packId) -> that pack's entry config from .claudinite-checks.json
87	//   existingIssuesFor(pack, task) -> the task family's issues [{number,title,state}]
88	// Returns `{ evaluations }`: one record per due task with its precondition
89	// verdict and, when it runs, either an inline marker (agent_model: none) or a
90	// dispatch decision (planDispatch).
91	export async function planRun({
92	  tasks, schedule, now, lastSuccess,
93	  collectSignals, packConfigFor = () => ({}), existingIssuesFor = async () => [],
94	}) {
95	  const dueList = computeDueTaskSlots(tasks, schedule, now, lastSuccess);
96	  const signals = await collectSignals(signalsUnion(dueList));
97	
98	  const evaluations = [];
99	  for (const { task, slotId } of dueList) {
100	    const pre = runPrecondition(task, signals, packConfigFor(task.pack));
101	    const rec = {
102	      pack: task.pack, task: task.id, slotId,
103	      model: task.decl.agent_model, outcome: task.decl.expected_outcome,
104	      run: pre.run, reason: pre.reason, context: pre.context,
105	    };
106	    if (pre.error) rec.error = pre.error;
107	    if (pre.run) {
108	      // A declared agent_preprocessing runs as a subprocess BEFORE any agent
109	      // (DESIGN §3) — flagged here (pure) for the summary; the CLI shell executes
110	      // it. An agentless task is preprocessing-only; an agentful one hands off to
111	      // the agent after preprocessing succeeds.
112	      if (task.decl.agent_preprocessing) rec.preprocessing = true;
113	      if (isAgentless(task.decl.agent_model)) {
114	        // agent_model: none — no agent and no dispatch issue on success. A task with
115	        // no preprocessing runs the legacy inline worker; with preprocessing it is
116	        // the subprocess above.
117	        rec.inline = true;
118	      } else {
119	        const existing = await existingIssuesFor(task.pack, task.id);
120	        // Route the dispatch to the self or fleet ready label by the task's scope
121	        // (the fleet/self executor split) — the executor routine wired to that
122	        // label runs it.
123	        const readyLabel = readyLabelForScope(task.decl.session_scope);
124	        rec.dispatch = planDispatch({ existing, pack: task.pack, task: task.id, slotId, readyLabel });
125	      }
126	    }
127	    evaluations.push(rec);
128	  }
129	  return { evaluations };
130	}
131	
132	// --- CLI: the thin I/O shell the vendored workflow invokes -------------------
133	// Wires the run-ledger read, signal collectors, and issue I/O around planRun,
134	// then acts on each decision (file a labeled dispatch issue, or run an inline
135	// worker) and prints the job summary. All GitHub access here is the Action's
136	// GITHUB_TOKEN — the one sanctioned non-MCP surface (DESIGN §10).
137	
138	// The task family's issues (state=all) via the search API, filtered to exact
139	// prefix — the input planDispatch's exactly-once / at-most-one-open guards read.
140	async function existingIssuesViaSearch(gh, repo, pack, task) {
141	  const q = encodeURIComponent(`repo:${repo} in:title "${DISPATCH_PREFIX} ${pack}/${task}"`);
142	  const { status, json } = await gh(`/search/issues?q=${q}&per_page=100`);
143	  if (status !== 200 || !Array.isArray(json?.items)) return [];
144	  const prefix = `${DISPATCH_PREFIX} ${pack}/${task} `;
145	  return json.items
146	    .filter((i) => `${(i.title ?? '').trim()} `.startsWith(prefix))
147	    .map((i) => ({ number: i.number, title: i.title, state: i.state }));
148	}
149	
150	// Every OPEN dispatch issue in the repo, with the labels / age / comment count the
151	// maintenance pass reads. Separate from existingIssuesViaSearch, which is per task
152	// family and state=all for the filing guards; this one is repo-wide and open-only.
153	export async function openDispatchIssuesViaSearch(gh, repo) {
154	  const q = encodeURIComponent(`repo:${repo} is:issue is:open in:title "${DISPATCH_PREFIX}"`);
155	  const { status, json } = await gh(`/search/issues?q=${q}&per_page=100`);
156	  if (status !== 200 || !Array.isArray(json?.items)) return [];
157	  return json.items.map((i) => ({
158	    number: i.number, title: i.title, labels: i.labels ?? [],
159	    created_at: i.created_at, updated_at: i.updated_at, comments: i.comments ?? 0,
160	  }));
161	}
162	
163	// The per-run maintenance pass over open dispatch issues (DESIGN §4 lifecycle,
164	// §5 recovery). Three backstops, in this order:
165	//   1. STALE — open past ~2 of its own scheduling periods → escalation comment,
166	//      drop the ready label (so it stops being armed), add `needs-human`.
167	//   2. DEAD CLAIM — `agent-running` with no activity for ~3h → the session that
168	//      claimed it died; comment, drop `agent-running`, add `needs-human`.
169	//   3. RE-ARM — armed but untouched past the grace window → the trigger event was
170	//      lost, so remove and re-add its ready label to emit a fresh one.
171	// Stale wins over re-arm: rearmDispatchIssues already excludes the stale set, so an
172	// issue converging to triage is never re-armed back into circulation.
173	//
174	// This is the ONLY recovery path for a missed label event or a dead session. The
175	// executor no longer sweeps other issues — one session runs exactly the one issue
176	// that triggered it — so recovery had to become a decision in code here, running
177	// once per scheduler run, rather than agent judgment replicated across every
178	// concurrently-triggered session.
179	export async function maintainDispatchIssues(gh, repo, now, { labelsEnsured = false } = {}) {
180	  const open = await openDispatchIssuesViaSearch(gh, repo);
181	  const none = { stale: [], deadClaims: [], rearmed: [] };
182	  if (!open.length) return none;
183	
184	  const stale = staleDispatchIssues(open, now);
185	  const staleNumbers = new Set(stale.map((i) => i.number));
186	  const deadClaims = staleClaimedDispatchIssues(open, now).filter((i) => !staleNumbers.has(i.number));
187	  const rearm = rearmDispatchIssues(open, now);
188	  if (!stale.length && !deadClaims.length && !rearm.length) return none;
189	
190	  // Applying a label 422s when it does not exist, so guarantee them first — an
191	  // idle run never gets here, so this costs nothing on the common path.
192	  if (!labelsEnsured) await ensureLabels(gh, repo, SCHEDULER_LABELS);
193	
194	  const escalate = async (issue, body, dropLabel) => {
195	    await gh(`/repos/${repo}/issues/${issue.number}/comments`, { method: 'POST', body: { body } });
196	    if (dropLabel) await gh(`/repos/${repo}/issues/${issue.number}/labels/${encodeURIComponent(dropLabel)}`, { method: 'DELETE' });
197	    await gh(`/repos/${repo}/issues/${issue.number}/labels`, { method: 'POST', body: { labels: [NEEDS_HUMAN_LABEL] } });
198	  };
199	
200	  for (const issue of stale) {
201	    await escalate(issue, staleEscalationComment(issue), readyLabelOn(issue));
202	    console.log(`- escalated stale dispatch #${issue.number} to ${NEEDS_HUMAN_LABEL}`);
203	  }
204	
205	  for (const issue of deadClaims) {
206	    await escalate(issue, staleClaimComment(issue), AGENT_RUNNING_LABEL);
207	    console.log(`- reclaimed dead ${AGENT_RUNNING_LABEL} claim on #${issue.number} → ${NEEDS_HUMAN_LABEL}`);
208	  }
209	
210	  for (const issue of rearm) {
211	    const ready = readyLabelOn(issue);
212	    const del = await gh(`/repos/${repo}/issues/${issue.number}/labels/${encodeURIComponent(ready)}`, { method: 'DELETE' });
213	    if (del.status >= 300) { console.log(`! could not un-label #${issue.number} to re-arm it: ${del.status}`); continue; }
214	    const add = await gh(`/repos/${repo}/issues/${issue.number}/labels`, { method: 'POST', body: { labels: [ready] } });
215	    if (add.status >= 300) console.log(`! re-arm of #${issue.number} dropped its ${ready} label: ${add.status}`);
216	    else console.log(`- re-armed #${issue.number} (${ready}) — its trigger event never landed`);
217	  }
218	
219	  return {
220	    stale: stale.map((i) => i.number),
221	    deadClaims: deadClaims.map((i) => i.number),
222	    rearmed: rearm.map((i) => i.number),
223	  };
224	}
225	
226	// Ensure the dispatch labels exist before any is applied — GitHub 422s when you
227	// apply an unknown label (it never creates one on demand), so the scheduler, as the
228	// thing that assigns them, guarantees them here. Idempotent (201 created / 422 already
229	// exists are both success) and self-healing (a deleted label reappears next run), which
230	// is why no separate one-off label-creation step is needed. Exported for the run tests.
231	export async function ensureLabels(gh, repo, labels) {
232	  for (const { name, color, description } of labels) {
233	    const res = await gh(`/repos/${repo}/labels`, { method: 'POST', body: { name, color, description } });
234	    if (res.status === 201) continue;                       // created to spec — nothing further
235	    if (res.status === 422) {
236	      // The NAME is taken; that says nothing about the colour or description. A
237	      // label GitHub auto-created (applying an unknown name to an issue mints it
238	      // grey `ededed`, no description) would keep those defaults for good, because
239	      // POST 422s forever. So reconcile the shape, not just the existence — that
240	      // is what makes the self-healing claim above true for drift and not only for
241	      // deletion. PATCH is idempotent: an already-correct label is a no-op write.
242	      const fix = await gh(`/repos/${repo}/labels/${encodeURIComponent(name)}`, {
243	        method: 'PATCH', body: { color, description },
244	      });
245	      if (fix.status !== 200) console.log(`! could not reconcile label "${name}": ${fix.status}`);
246	      continue;
247	    }
248	    console.log(`! could not ensure label "${name}": ${res.status}`);
249	  }
250	}
251	
252	async function main() {
253	  const { makeGh, lastSuccessTime, actionRepoContext } = await import('./signals/gh.mjs');
254	  const { collectSignals } = await import('./signals/index.mjs');
255	  const { discoverTasks } = await import('./discover.mjs');
256	  const { loadConfig } = await import('../checks/helpers/repo-context.mjs');
257	
258	  const root = process.cwd();
259	  const { repo, defaultBranch } = actionRepoContext();
260	  if (!repo) { console.error('GITHUB_REPOSITORY not set — not in an Actions context'); process.exit(1); }
261	  const gh = makeGh();
262	  const config = loadConfig(root);
263	
264	  const { tasks, errors } = await discoverTasks(root, config);
265	  for (const e of errors) console.log(`! ${e.what}`);
266	
267	  const now = new Date();
268	  const lastSuccess = await lastSuccessTime(gh, repo);
269	  const schedule = config.taskScheduler;
270	
271	  const due = computeDueTaskSlots(tasks, schedule, now, lastSuccess);
272	  const sinceIso = windowStart(due, now);
273	
274	  // The fleet aggregate (canon-only, DESIGN §3.3) is expensive — a full
275	  // enumeration over the fleet PAT — so build it ONLY when a due task actually
276	  // declares the `fleet` signal, and only when FLEET_GITHUB_TOKEN is set (the
277	  // canon repo with the census credential). Otherwise ctx.fleet stays null and
278	  // the collector returns null, so a fleet task's precondition skips rather than
279	  // crashes. Enumeration failures are surfaced by readFleet as `{ error }`, not
280	  // thrown — a fleet task treats that as "no work I can prove".
281	  let fleet = null;
282	  if (signalsUnion(due).includes('fleet')) {
283	    const { readFleet, makeFleetGh } = await import('./signals/fleet.mjs');
284	    const fleetGh = makeFleetGh();
285	    if (fleetGh) {
286	      const owner = repo.split('/')[0];
287	      fleet = await readFleet(fleetGh, { owner, canonRepo: repo, sinceIso });
288	      if (fleet.error) console.log(`! fleet enumeration: ${fleet.error}`);
289	    } else {
290	      console.log('- a due task declares the `fleet` signal but FLEET_GITHUB_TOKEN is not set — skipping fleet-scoped tasks');
291	    }
292	  }
293	
294	  const ctx = {
295	    repo, defaultBranch, now: now.toISOString(), sinceIso, config,
296	    activePacks: config.packs, fleet,
297	  };
298	  const packConfigFor = (packId) => config.packConfig?.[packId] ?? {};
299	
300	  const { evaluations } = await planRun({
301	    tasks, schedule, now, lastSuccess,
302	    collectSignals: (names) => collectSignals(gh, ctx, names),
303	    packConfigFor,
304	    existingIssuesFor: (pack, task) => existingIssuesViaSearch(gh, repo, pack, task),
305	  });
306	
307	  // Guarantee the dispatch labels exist before we file any labeled issue — when a
308	  // task will dispatch OR will run preprocessing (which may converge to
309	  // needs-human). An idle run pays nothing.
310	  const labelsEnsured = evaluations.some((r) => r.run && (r.preprocessing || (!r.inline && r.dispatch?.action === 'create')));
311	  if (labelsEnsured) await ensureLabels(gh, repo, SCHEDULER_LABELS);
312	
313	  // File the labeled hand-off issue the executor runs (READY_LABEL): first line is
314	  // the task path, body carries the precondition's binding Context (dispatch.mjs).
315	  const fileHandoff = async (rec, taskObj) => {
316	    const title = dispatchTitle({ pack: rec.pack, task: rec.task, slotId: rec.slotId });
317	    const body = dispatchBody({ taskPath: taskObj.taskPath, pack: rec.pack, task: rec.task, slotId: rec.slotId, context: rec.context });
318	    // The scope-resolved ready label (self vs fleet) from planDispatch — the
319	    // executor routine wired to it runs the task.
320	    const readyLabel = rec.dispatch?.label ?? READY_LABEL;
321	    const res = await gh(`/repos/${repo}/issues`, { method: 'POST', body: { title, body, labels: [readyLabel] } });
322	    if (res.status >= 300) console.log(`! failed to file dispatch issue for ${rec.pack}/${rec.task}: ${res.status}`);
323	  };
324	
325	  // Converge a failed preprocessing run to a single open needs-human issue for the
326	  // family — at-most-one-open, so a repeatedly-failing task never spams issues.
327	  const fileNeedsHuman = async (rec, why, extra) => {
328	    const existing = await existingIssuesViaSearch(gh, repo, rec.pack, rec.task);
329	    if (existing.some((i) => i.state === 'open')) {
330	      console.log(`  (an open dispatch issue already covers ${rec.pack}/${rec.task} — not filing another)`);
331	      return;
332	    }
333	    const title = dispatchTitle({ pack: rec.pack, task: rec.task, slotId: rec.slotId });
334	    const body = [
335	      `Preprocessing for \`${rec.pack}/${rec.task}\` (slot \`${rec.slotId}\`) failed and needs human triage.`,
336	      '', `- ${why}`, ...extra.map((e) => `- ${e}`),
337	    ].join('\n') + '\n';
338	    const res = await gh(`/repos/${repo}/issues`, { method: 'POST', body: { title, body, labels: [NEEDS_HUMAN_LABEL] } });
339	    if (res.status >= 300) console.log(`! failed to file needs-human issue for ${rec.pack}/${rec.task}: ${res.status}`);
340	  };
341	
342	  for (const rec of evaluations) {
343	    if (!rec.run) continue;
344	    const taskObj = tasks.find((t) => t.pack === rec.pack && t.id === rec.task);
345	    const decl = taskObj.decl;
346	
347	    // Stage 1 — preprocessing (DESIGN §3): run the declared command as a subprocess
348	    // bounded by its timeout, before any agent. Its cwd is the task dir; the repo
349	    // root + slot context ride in via CLAUDINITE_* env.
350	    if (rec.preprocessing) {
351	      // A per-run signal path the worker writes to REQUEST the agent stage
352	      // (conditional handoff, §3). Clear any stale one first so a prior run can't
353	      // spuriously escalate this one.
354	      const requestPath = agentRequestPath(rec);
355	      clearAgentRequest(requestPath);
356	      const result = await runPreprocessing(decl.agent_preprocessing, {
357	        taskDir: taskObj.taskDir,
358	        env: {
359	          ...process.env,
360	          CLAUDINITE_REPO_ROOT: root,
361	          CLAUDINITE_REPO: repo,
362	          CLAUDINITE_DEFAULT_BRANCH: defaultBranch ?? '',
363	          CLAUDINITE_SLOT_ID: rec.slotId,
364	          CLAUDINITE_PACK: rec.pack,
365	          CLAUDINITE_TASK: rec.task,
366	          CLAUDINITE_REQUEST_AGENT: requestPath,
367	        },
368	        timeoutSeconds: decl.agent_preprocessing_timeout,
369	      });
370	      rec.preprocessResult = { ok: result.ok, timedOut: result.timedOut, code: result.code };
371	      if (!result.ok) {
372	        const why = preprocessingFailure(result);
373	        console.log(`! preprocessing ${rec.pack}/${rec.task} [${rec.slotId}]: ${why}`);
374	        const extra = result.stderr?.trim() ? [`stderr tail: ${result.stderr.trim().split('\n').slice(-3).join(' / ')}`] : [];
375	        await fileNeedsHuman(rec, why, extra);
376	        clearAgentRequest(requestPath);
377	        continue; // never hand off to an agent after a failed preprocessing
378	      }
379	      // Success. An agentless task is done (no issue on success, as the old inline
380	      // was quiet). An agentful one hands off ONLY when the worker requested the
381	      // agent (conditional escalation, §3): a task that absorbs its work into
382	      // preprocessing stays quiet on the nights nothing needs judgment.
383	      const requested = agentRequested(requestPath);
384	      clearAgentRequest(requestPath);
385	      rec.agentRequested = requested;
386	      console.log(`preprocessing ${rec.pack}/${rec.task} [${rec.slotId}]: ok${rec.inline ? '' : requested ? ' (agent requested)' : ' (no agent needed)'}`);
387	      if (rec.inline) continue;
388	      if (requested && rec.dispatch?.action === 'create') await fileHandoff(rec, taskObj);
389	      continue;
390	    }
391	
392	    // No preprocessing. An agentless task with no preprocessing does nothing — the
393	    // contract now forbids it (agent_model:none REQUIRES agent_preprocessing, so
394	    // the in-process inline worker path is retired, DESIGN §4). Defensive no-op
395	    // should one slip past validation.
396	    if (rec.inline) {
397	      console.log(`- ${rec.pack}/${rec.task}: agentless with no preprocessing — nothing to run (contract-forbidden)`);
398	      continue;
399	    }
400	    // Agent task with no preprocessing → today's immediate labeled dispatch.
401	    if (rec.dispatch?.action === 'create') await fileHandoff(rec, taskObj);
402	  }
403	
404	  // Maintenance over the open dispatch issues, AFTER this run's filings: the
405	  // issues just filed are seconds old, so the grace window keeps them out of the
406	  // re-arm set and only the previous cycles' leftovers are considered.
407	  await maintainDispatchIssues(gh, repo, now, { labelsEnsured });
408	
409	  console.log('## Claudinite scheduler\n');
410	  console.log(renderSummary(evaluations) || '- no tasks due');
411	}
412	
413	// Run only when invoked directly (the workflow's `node run.mjs`), never on import.
414	if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
415	  main().catch((e) => { console.error(e); process.exit(1); });
416	}
